/** Determines whether a `value` that has already been recursively processed should be considered "empty" for the
 * purposes of pruning. A value is empty when it is `undefined`, `null`, an empty string, or an empty array. Note that
 * boolean `false` and the number `0` are explicitly NOT considered empty.
 *
 * @param value - The processed value to test for emptiness
 * @returns - True if the `value` is considered empty, false otherwise
 */
function isEmpty(value: any): boolean {
  if (value === undefined || value === null || value === '') {
    return true;
  }
  if (Array.isArray(value) && value.length === 0) {
    return true;
  }
  return false;
}

/** Recursively traverses `formData` against the given `schema` and removes any optional properties (object, scalar, or
 * array) whose values are considered "empty" (`undefined`, `null`, an empty string, an empty array, or a nested object
 * that is itself fully empty after processing). Required properties (those listed in the schema's `required` array) are
 * NOT removed; if a required property's value is processed to empty, its key is retained but set to `undefined`.
 * Properties present in `formData` but not defined in the `schema` are preserved as-is. When all properties of an
 * object are pruned, the function returns `undefined` instead of an empty object. Arrays are processed item-by-item
 * using the appropriate per-item schema (tuple items by index, `additionalItems` for out-of-bounds indices, or as-is
 * when no schema applies). Boolean `false` and the number `0` are NOT considered empty.
 *
 * @param validator - An implementation of the `ValidatorType` interface that is used to detect valid schema conditions
 * @param schema - The schema against which the `formData` is processed
 * @param rootSchema - The root schema, used to primarily to look up `$ref`s
 * @param formData - The form data on which the optional empty objects will be removed
 * @returns - The `formData` with optional empty objects removed, or `undefined` if the entire `formData` is empty
 */
export default function removeOptionalEmptyObjects<
  T = any,
  S extends StrictRJSFSchema = RJSFSchema,
  F extends FormContextType = any,
>(validator: ValidatorType<T, S, F>, schema: S, rootSchema: S, formData: any): any | undefined {
  if (formData === undefined) {
    return undefined;
  }

  // Nothing to process for non-object, non-array values or when there is no schema to process against.
  if ((!isObject(formData) && !Array.isArray(formData)) || !schema) {
    return formData;
  }

  if (Array.isArray(formData)) {
    const items = schema[ITEMS_KEY];
    if (items === undefined) {
      return formData;
    }
    let changed = false;
    const result = formData.map((item, index) => {
      let itemSchema: S | undefined;
      if (Array.isArray(items)) {
        if (index < items.length) {
          itemSchema = items[index] as S;
        } else if (schema[ADDITIONAL_ITEMS_KEY] && isObject(schema[ADDITIONAL_ITEMS_KEY])) {
          itemSchema = schema[ADDITIONAL_ITEMS_KEY] as S;
        }
      } else if (isObject(items)) {
        itemSchema = items as S;
      }
      if (!itemSchema) {
        return item;
      }
