  const properties = schema[PROPERTIES_KEY];
  if (!properties) {
    return formData;
  }

  const required: string[] = Array.isArray(schema[REQUIRED_KEY]) ? (schema[REQUIRED_KEY] as string[]) : [];
  const result: { [key: string]: any } = { ...formData };

  Object.keys(properties).forEach((key) => {
    if (!(key in result)) {
      return;
    }
    const propertySchema = properties[key] as S;
    const processed = removeOptionalEmptyObjects<T, S, F>(validator, propertySchema, rootSchema, result[key]);
    if (isEmpty(processed)) {
      if (required.includes(key)) {
        result[key] = undefined;
      } else {
        delete result[key];
      }
    } else {
      result[key] = processed;
    }
  });

  // If every remaining property is either absent or explicitly `undefined`, there is no meaningful data left, so the
  // whole object collapses to `undefined`.
  const hasMeaningfulData = Object.keys(result).some((key) => result[key] !== undefined);
